export async function waitForSubscribed(channel, timeoutMs = 6000): Promise<boolean> {
  return new Promise((resolve) => {
    let done = false;
    const t = window.setTimeout(() => { if(!done){done=true;resolve(false);} }, timeoutMs);
    channel.subscribe((status) => { if (status === 'SUBSCRIBED' && !done) {done=true; clearTimeout(t); resolve(true);} });
