{"kind":"tool","id":"l5hY0GQBuus","toolName":"write_file","input":{"path":"src-app/src/features/help/HelpCenter.tsx","content":"/**
 * HelpCenter.tsx — Ajuda e Tutoriais (v4.66.0)
 *
 * FAQ do app escrita a partir das diretrizes (DESIGN.md/README.md): como
 * montar a ficha, treinar no modo foco, entender o progresso, usar o Social
 * (ranking global + amigos), funcionar offline e cuidar da conta.
 *
 * A tela fica dentro de Configurações → Ajuda e Tutoriais (tile raiz).
 */

import { useMemo, useState } from 'react';
import {
  ChevronDown,
  Cloud,
  Dumbbell,
  HelpCircle,
  LayoutGrid,
  LineChart,
  Trophy,
  Users,
  WifiOff,
} from 'lucide-react';
import './help.css';

interface FaqItem {
  q: string;
  a: string;
}

interface FaqGroup {
  id: string;
  title: string;
  icon: React.ReactNode;
  items: FaqItem[];
}

const GROUPS: FaqGroup[] = [
  {
    id: 'comecando',
    title: 'Começando',
    icon: <HelpCircle size={16} />,
    items: [
      {
        q: 'Como começo a usar o app?',
        a: 'No primeiro acesso você escolhe um nome de usuário e preenche o formulário pós-login (nascimento, sexo, altura e peso). Esses dados viram o seu Perfil de Saúde e podem ser ajustados depois: peso e altura são editáveis a qualquer momento e também acompanham as métricas corporais da aba Progresso.',
      },
      {
        q: 'Preciso criar uma ficha antes de treinar?',
        a: 'Sim. Em Treino → Minha Ficha você monta a ficha do dia (de 1 a 8 exercícios por ficha) e o app sugere a próxima ficha automaticamente  [… 6,492 characters omitted]    >
        <span>{item.q}</span>
        <ChevronDown size={14} className="help-item__chev" aria-hidden="true" />
      </button>
      <div className="help-item__answer-wrap" aria-hidden={!open}>
        <p className="help-item__answer">{item.a}</p>
      </div>
    </div>
  );
}

export function HelpCenter() {
  const [query, setQuery] = useState('');

  const groups = useMemo(() => {
    const term = query.trim().toLowerCase();
    if (!term) return GROUPS;
    return GROUPS.map((group) => ({
      ...group,
      items: group.items.filter(
        (item) =>
          item.q.toLowerCase().includes(term) || item.a.toLowerCase().includes(term),
      ),
    })).filter((group) => group.items.length > 0);
  }, [query]);

  return (
    <div className="help-root">
      <section className="set-card help-intro">
        <div className="set-card__head">
          <div>
            <div className="set-card__eyebrow">CENTRAL DE AJUDA</div>
            <h3 className="set-card__title">Como o EVO FIT funciona</h3>
            <p className="set-card__desc">
              Perguntas frequentes sobre ficha, treino, progresso, ranking e conta. Busque por uma
              palavra para filtrar.
            </p>
          </div>
        </div>
        <input
          type="search"
          className="set-input help-search"
          placeholder="Buscar na ajuda (ex.: offline, ranking, foco)"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          aria-label="Buscar na ajuda"
        />
      </section>

      {groups.length === 0 && (
        <p className="help-empty">Nenhuma resposta encontrada para “{query.trim()}”.</p>
      )}

      {groups.map((group) => (
        <section className="set-card help-group" key={group.id}>
          <div className="help-group__head">
            <span className="help-group__icon" aria-hidden="true">
              {group.icon}
            </span>
            <h3 className="help-group__title">{group.title}</h3>
          </div>
          <div className="help-list">
            {group.items.map((item) => (
              <Accordion key={item.q} item={item} />
            ))}
          </div>
        </section>
      ))}
    </div>
  );
}

export default HelpCenter;
"}}


{"kind":"tool","id":"l5iC68AtBBI","toolName":"write_file","input":{"path":"src-app/src/features/help/help.css","instructions":"Estilos da nova tela de Ajuda com acordeão animado","content":"/* ============================================================
   HELP — Ajuda e Tutoriais (v4.66.0)

   Reaproveita o HUD dark do design system `set-*` (settings.css):
   cards, eyebrow, títulos e inputs. Aqui ficam só os grupos e o
   acordeão, com transição suave de abertura/fechamento (grid-rows
   0fr → 1fr + opacidade), sem saltos de layout.
   ============================================================ */

.help-root {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.help-search {
  width: 100%;
  margin-top: 4px;
}

.help-group {
  display: block;
}

.help-group__head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.help-group__icon {
  width: 32px;
  height: 32px;
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: rgba(var(--primary-rgb, 139, 92, 246), 0.14);
  border: 1px solid rgba(var(--primary-rgb, 139, 92, 246), 0.4);
  color: var(--primary-light);
}

.help-group__title {
  margin: 0;
  font-size: 0.86rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text);
}

.help-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* ---------- Acordeão ---------- */

.help-item {
  border: 1px solid rgba(63, 63, 70, 0.7);
  border-radius: 14px;
  background: rgba(24, 24, 27, 0.72);
  overflow: hidden;
  transition:
    border-color 0.22s ease,
    background-color 0.22s ease;
}

.help-item.is-open,
.help-item:hover {
  border-color: rgba(var(--primary-rgb, 139, 92, 246), 0.45);
}

.help-item__question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 14px;
  background: transparent;
  border: 0;
  cursor: pointer;
  text-align: left;
  font-size: 0.82rem;
  font-weight: 800;
  color: var(--text);
  transition: color 0.2s ease;
}

.help-item__question:hover {
  color: var(--primary-light);
}

.help-item__chev {
  flex-shrink: 0;
  color: var(--set-dim-2, #71717a);
  transition: transform 0.26s cubic-bezier(0.25, 0.8, 0.25, 1), color 0.2s ease;
}

.help-item.is-open .help-item__chev {
  transform: rotate(180deg);
  color: var(--primary-light);
}

.help-item__answer-wrap {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transition:
    grid-template-rows 0.3s cubic-bezier(0.25, 0.8, 0.25, 1),
    opacity 0.26s ease;
}

.help-item.is-open .help-item__answer-wrap {
  grid-template-rows: 1fr;
  opacity: 1;
}

.help-item__answer {
  min-height: 0;
  overflow: hidden;
  margin: 0;
  padding: 0 14px;
  font-size: 0.76rem;
  line-height: 1.65;
  color: var(--text-secondary, #a1a1aa);
  transition: padding 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
}

.help-item.is-open .help-item__answer {
  padding: 0 14px 14px;
}

.help-empty {
  margin: 0;
  padding: 18px 4px;
  text-align: center;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--text-tertiary, #71717a);
}

@media (prefers-reduced-motion: reduce) {
  .help-item,
  .help-item__chev,
  .help-item__answer-wrap,
  .help-item__answer {
    transition: none !important;
  }
}
"}}


